param([switch]$SkipTests,[string]$DistributionDirectory='dist')
$ErrorActionPreference='Stop'
$root=$PSScriptRoot
if(!$SkipTests){$env:SCREENCRAFT_TEST_OUTPUT=Join-Path $root 'docs\evidence\automated';& (Join-Path $root 'build.ps1') -Test}
& (Join-Path $root 'build.ps1')
$dist=if([IO.Path]::IsPathRooted($DistributionDirectory)){[IO.Path]::GetFullPath($DistributionDirectory)}else{[IO.Path]::GetFullPath((Join-Path $root $DistributionDirectory))}
$stage=Join-Path $root ('.build\package-'+[guid]::NewGuid().ToString('N'))
$portable=Join-Path $stage 'ScreenCraft-Portable'
New-Item -ItemType Directory -Force $dist,$portable,(Join-Path $portable 'Data') | Out-Null
Copy-Item (Join-Path $root 'bin\Release\ScreenCraft.exe'),(Join-Path $root 'bin\Release\ScreenCraft.exe.config'),(Join-Path $root 'LICENSE'),(Join-Path $root 'THIRD_PARTY_NOTICES.md') -Destination $portable
Copy-Item (Join-Path $root 'docs\USER_GUIDE.md'),(Join-Path $root 'docs\KNOWN_LIMITATIONS.md') -Destination $portable
Copy-Item -LiteralPath (Join-Path $root 'src\Assets\COLORBREWER_LICENSE.txt') -Destination (Join-Path $portable 'COLORBREWER_LICENSE.txt')
Copy-Item -LiteralPath (Join-Path $root 'src\Assets\WIX_LICENSE.txt') -Destination (Join-Path $portable 'WIX_LICENSE.txt')
Set-Content -LiteralPath (Join-Path $portable 'portable.flag') -Value 'ScreenCraft portable mode'
Set-Content -LiteralPath (Join-Path $portable 'Data\README.txt') -Value 'Preferences are written here when the user saves settings. Startup entries remain per machine/user.'
$zip=Join-Path $dist 'ScreenCraft-Portable-win-x64.zip'
Compress-Archive -LiteralPath $portable -DestinationPath $zip -Force
& (Join-Path $root 'tools\build-installer.ps1') -DistributionDirectory $dist
& (Join-Path $root 'tools\inspect-installer.ps1') -InstallerPath (Join-Path $dist 'ScreenCraft-Setup-PerUser-win-x64.msi')
$source=Join-Path $stage 'ScreenCraft-Source'
New-Item -ItemType Directory -Force $source | Out-Null
foreach($folder in 'src','tests','tools'){Copy-Item -LiteralPath (Join-Path $root $folder) -Destination $source -Recurse}
New-Item -ItemType Directory -Force (Join-Path $source 'docs') | Out-Null
Get-ChildItem (Join-Path $root 'docs') -File | Copy-Item -Destination (Join-Path $source 'docs')
if(Test-Path (Join-Path $root 'docs\images')){Copy-Item -LiteralPath (Join-Path $root 'docs\images') -Destination (Join-Path $source 'docs\images') -Recurse}
# Automated evidence uses synthetic fixtures; private desktop captures stay in the local evidence folder.
New-Item -ItemType Directory -Force (Join-Path $source 'docs\evidence') | Out-Null
New-Item -ItemType Directory -Force (Join-Path $source 'docs\evidence\automated') | Out-Null
# Long-path fixtures are generated by tests. Ship their flat PNG/JSON/log evidence, not deep input-free folders.
Get-ChildItem (Join-Path $root 'docs\evidence\automated') | Where-Object Name -ne 'long-png' | Copy-Item -Destination (Join-Path $source 'docs\evidence\automated') -Recurse
if(Test-Path (Join-Path $root 'docs\evidence\m3')){Copy-Item -LiteralPath (Join-Path $root 'docs\evidence\m3') -Destination (Join-Path $source 'docs\evidence\m3') -Recurse}
if(Test-Path (Join-Path $root 'docs\evidence\hotkey-input')){Copy-Item -LiteralPath (Join-Path $root 'docs\evidence\hotkey-input') -Destination (Join-Path $source 'docs\evidence\hotkey-input') -Recurse}
if(Test-Path (Join-Path $root 'docs\evidence\in-place')){Copy-Item -LiteralPath (Join-Path $root 'docs\evidence\in-place') -Destination (Join-Path $source 'docs\evidence\in-place') -Recurse}
if(Test-Path (Join-Path $root '.impeccable\design.json')){New-Item -ItemType Directory -Force (Join-Path $source '.impeccable') | Out-Null;Copy-Item -LiteralPath (Join-Path $root '.impeccable\design.json') -Destination (Join-Path $source '.impeccable\design.json')}
Get-ChildItem $root -File | Where-Object {$_.Extension -in '.md','.ps1' -or $_.Name -in 'LICENSE','.gitignore','.gitattributes'} | Copy-Item -Destination $source
Compress-Archive -LiteralPath $source -DestinationPath (Join-Path $dist 'ScreenCraft-Source.zip') -Force
Copy-Item -LiteralPath (Join-Path $root 'bin\Release\ScreenCraft.exe') -Destination (Join-Path $dist 'ScreenCraft.exe') -Force
Copy-Item -LiteralPath (Join-Path $root 'bin\Release\ScreenCraft.exe.config') -Destination (Join-Path $dist 'ScreenCraft.exe.config') -Force
$hashes=@(Get-ChildItem $dist -File | Where-Object Name -ne 'SHA256SUMS.txt' | Sort-Object Name | ForEach-Object { (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()+'  '+$_.Name })
Set-Content -LiteralPath (Join-Path $dist 'SHA256SUMS.txt') -Value $hashes
Write-Output "Packaged development preview: $dist"
